sys_variable_value.value:
// ATF injects assertEqual, steps, outputs, stepResult and an enclosing try block - bare body.
// steps(SYS_ID) is ATF's injected accessor for an earlier step's outputs. GEM {{ step[...] }}
// templates are NOT substituted in a script body, so the sys_id must be passed literally.
var productId = steps("c794da2ea5a641529d7bf7bce9844411").record_id;
if (!productId || ('' + productId).length !== 32) {
    throw new Error('unresolved step reference for productId: ' + productId);
}
var calc = new x_2298436_snackf_0.SnackFlowCalc();

// Independent recomputation straight off the ledger.
var ledger = calc.ledgerBalance('finished_product', productId, null);
assertEqual({ name: 'ledger balance after +100 -30 +5', shouldbe: 75, value: ledger });

// Derived stock_bal row must agree, and there must be exactly one of them.
var rows = 0, stored = null, below = null, reorder = null;
var sb = new GlideRecord('x_2298436_snackf_0_stock_bal');
sb.addQuery('product', productId);
sb.query();
while (sb.next()) {
    rows++;
    stored = parseFloat(sb.getValue('current_balance'));
    below = sb.getValue('below_reorder');
    reorder = parseFloat(sb.getValue('reorder_level')) || 0;
}
assertEqual({ name: 'exactly one stock_bal row for the item (upsert, no duplicates)', shouldbe: 1, value: rows });
assertEqual({ name: 'stock_bal.current_balance matches the ledger', shouldbe: ledger, value: stored });
assertEqual({ name: 'below_reorder false when reorder level is 0', shouldbe: '0', value: '' + below });

outputs.product_id = productId;
stepResult.setOutputMessage('ledger=' + ledger + ' stock_bal=' + stored + ' rows=' + rows + ' reorder=' + reorder);
